corporate_design.toad_component_blueprint:
canvas {
  size: 880px 580px;
  fill: #FFF8ED;
  font-family: "Plus Jakarta Sans, sans-serif";
}

>yellow = #FBBF24;
>brown = #451A03;

rect #oatCard {
  at: center of canvas;
  size: 780px 480px;
  fill: #FFFFFF;
  stroke: >yellow;
  stroke-width: 2px;
  radius: 24px;
}

text #oatBrand {
  at: top left of #oatCard offset 40px 40px;
  content: "HAFERGLÜCK // BIO BARISTA EDITION";
  font-size: 14px;
  font-weight: 800;
  color: >yellow;
}

text #oatClaim {
  at: below #oatBrand offset 14px;
  content: "100% Pflanzlich. Perfekt geschäumt.";
  font-size: 34px;
  font-weight: 800;
  color: >brown;
}
